def resolve(path, cwd, links):
    if not isinstance(path, str) or not isinstance(cwd, str) or not isinstance(links, dict):
        return None

    # Start with cwd if path is relative, otherwise start with root
    if path.startswith('/'):
        current = '/'
        components = path[1:].split('/')
    else:
        current = cwd
        components = path.split('/')

    link_count = 0
    max_links = 8

    i = 0
    while i < len(components):
        comp = components[i]
        i += 1

        # Skip empty components and '.'
        if comp == '' or comp == '.':
            continue

        # Handle '..'
        if comp == '..':
            if current != '/':
                # Move to parent
                current = current.rsplit('/', 1)[0]
                if current == '':
                    current = '/'
            # If current is '/', stay at '/'
            continue

        # Append the component
        if current == '/':
            candidate = '/' + comp
        else:
            candidate = current + '/' + comp

        # Check if this is a symlink
        if candidate in links:
            link_count += 1
            if link_count > max_links:
                return None

            target = links[candidate]

            # Parse the target
            if target.startswith('/'):
                # Absolute target
                current = '/'
                new_components = target[1:].split('/')
            else:
                # Relative target - relative to the directory containing the link
                current = candidate.rsplit('/', 1)[0]
                if current == '':
                    current = '/'
                new_components = target.split('/')

            # Prepend remaining components and continue
            components = new_components + components[i:]
            i = 0
        else:
            # Not a symlink, just update current
            current = candidate

    # Remove trailing slash except for '/'
    if current != '/' and current.endswith('/'):
        current = current.rstrip('/')

    return current

